import pytest
from candidate import car_race_collision

def test_car_race_collision_normal_n1():
    assert car_race_collision(1) == 1

def test_car_race_collision_normal_n2():
    assert car_race_collision(2) == 4

def test_car_race_collision_normal_n5():
    assert car_race_collision(5) == 25

def test_car_race_collision_zero_input():
    assert car_race_collision(0) == 0

def test_car_race_collision_negative_input():
    assert car_race_collision(-3) == 9

def test_car_race_collision_float_input():
    assert car_race_collision(4.0) == 16.0

def test_car_race_collision_large_n():
    assert car_race_collision(100) == 10000

def test_car_race_collision_string_raises_type_error():
    with pytest.raises(TypeError):
        car_race_collision("5")

def test_car_race_collision_none_raises_type_error():
    with pytest.raises(TypeError):
        car_race_collision(None)

def test_car_race_collision_list_raises_type_error():
    with pytest.raises(TypeError):
        car_race_collision([1, 2])
